from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
families=[]
def F(ident,scope,files,found,limits):
    queries=[]
    for n in files:
        p=ROOT/'outputs'/f'web_{n:02d}.json'
        if not p.exists():continue
        data=json.loads(p.read_text());req=data.get('request',{})
        for typ in ['system1_search_query','system2_search_query']:
            for q in req.get(typ,[]) or []:queries.append(dict(engine=typ,query=q,log=str(p.relative_to(ROOT))))
    families.append(dict(id=ident,scope=scope,search_date='2026-11-19',raw_logs=[f'outputs/web_{n:02d}.json' for n in files],queries=queries,checked_hits=found,limitations_and_unsuccessful_searches=limits,negative_evidence_rule='No-hit or blocked channel is weak evidence only; no assertion of nonexistence or historical priority follows. References were followed backwards when later works gave an identifiable predecessor.'))
